using System.Text.RegularExpressions;

namespace Makari.Api.Features.Customers.Domain;

public sealed class Customer
{
    private Customer() { }
    public Customer(string username)
    {
        if (!TryNormalize(username, out var normalized))
            throw new ArgumentException(UsernameRule, nameof(username));
        Id = Guid.NewGuid();
        Username = normalized;
    }

    public Guid Id { get; private set; }
    public string Username { get; private set; } = null!;
    // Generated by the database: callers cannot bypass case-insensitive uniqueness.
    public string NormalizedUsername { get; private set; } = null!;
    public static readonly Guid VisitorId = Guid.Parse("a1200000-0000-4000-8000-000000000001");
    public static readonly Guid LocalId = Guid.Parse("a1200000-0000-4000-8000-000000000002");
    public const string UsernameRule = "Use 1–40 characters: ASCII letters, digits, spaces, dot, underscore or hyphen; start with a letter or digit.";

    public static bool TryNormalize(string? value, out string username)
    {
        username = "";
        if (value is null || value.Length > 256) return false;
        var clean = Regex.Replace(value.Trim(), @"\s+", " ");
        if (!Regex.IsMatch(clean, @"\A[A-Za-z0-9][A-Za-z0-9 ._-]{0,39}\z")) return false;
        username = clean.ToLowerInvariant() switch { "visitante" => "visitante", "local" => "local", _ => clean };
        return true;
    }
}
